content:
:root {
  --bg-body: #f0f2f5;
  --bg-calculator: #22252d;
  --bg-display: #2a2d37;
  --color-text: #ffffff;
  --btn-number-bg: #3b3f4c;
  --btn-number-hover: #484c5c;
  --btn-operator-bg: #ff9f0a;
  --btn-operator-hover: #ffb12c;
  --btn-action-bg: #a5a5ad;
  --btn-action-hover: #b8b8c0;
  --btn-action-text: #000000;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
}

body {
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 100vh;
  background-color: var(--bg-body);
}

.calculator {
  width: 100%;
  max-width: 360px;
  background-color: var(--bg-calculator);
  border-radius: 24px;
  padding: 24px;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.3);
}

.display {
  background-color: var(--bg-display);
  color: var(--color-text);
  font-size: 2.5rem;
  font-weight: 300;
  text-align: right;
  padding: 20px;
  border-radius: 16px;
  margin-bottom: 24px;
  word-break: break-all;
  min-height: 80px;
  display: flex;
  align-items: flex-end;
  justify-content: flex-end;
}

.keypad {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 12px;
}

.btn {
  background-color: var(--btn-number-bg);
  color: var(--color-text);
  border: none;
  border-radius: 12px;
  font-size: 1.25rem;
  font-weight: 500;
  height: 60px;
  cursor: pointer;
  transition: background-color 0.2s ease, transform 0.1s ease, filter 0.2s ease;
  display: flex;
  align-items: center;
  justify-content: center;
  user-select: none;
}

.btn:active {
  transform: scale(0.95);
  filter: brightness(0.9);
}

.btn-number {
  background-color: var(--btn-number-bg);
}

.btn-number:hover {
  background-color: var(--btn-number-hover);
}

.btn-operator {
  background-color: var(--btn-operator-bg);
  color: var(--color-text);
}

.btn-operator:hover {
  background-color: var(--btn-operator-hover);
}

.btn-action {
  background-color: var(--btn-action-bg);
  color: var(--btn-action-text);
}

.btn-action:hover {
  background-color: var(--btn-action-hover);
}

.btn-zero {
  grid-column: span 2;
  border-radius: 30px;
  justify-content: center;
  padding-left: 0;
}

import { useState } from 'react';
import './index.css';

function useCalculator() {
  const [displayValue, setDisplayValue] = useState('0');
  const [prevValue, setPrevValue] = useState<number | null>(null);
  const [operator, setOperator] = useState<string | null>(null);
  const [waitingForOperand, setWaitingForOperand] = useState(false);

  const clearAll = () => {
    setDisplayValue('0');
    setPrevValue(null);
    setOperator(null);
    setWaitingForOperand(false);
  };

  const toggleSign = () => {
    const value = parseFloat(displayValue);
    if (value === 0) return;
    setDisplayValue(value > 0 ? `-${displayValue}` : displayValue.slice(1));
  };

  const inputPercent = () => {
    const value = parseFloat(displayValue);
    const result = value / 100;
    setDisplayValue(String(parseFloat(result.toFixed(10))));
  };

  const inputDigit = (digit: string) => {
    if (waitingForOperand) {
      setDisplayValue(digit);
      setWaitingForOperand(false);
    } else {
      setDisplayValue(displayValue === '0' ? digit : displayValue + digit);
    }
  };

  const inputDot = () => {
    if (waitingForOperand) {
      setDisplayValue('0.');
      setWaitingForOperand(false);
      return;
    }
    if (!displayValue.includes('.')) {
      setDisplayValue(displayValue + '.');
    }
  };

  const performCalculation = (left: number, right: number, op: string): number => {
    let result = 0;
    switch (op) {
      case '+':
        result = left + right;
        break;
      case '-':
        result = left - right;
        break;
      case '×':
        result = left * right;
        break;
      case '÷':
        result = right === 0 ? 0 : left / right;
        break;
      default:
        result = right;
    }
    return parseFloat(result.toFixed(10));
  };

  const handleOperator = (nextOperator: string) => {
    const inputValue = parseFloat(displayValue);

    if (prevValue === null) {
      setPrevValue(inputValue);
    } else if (operator) {
      const currentVal = prevValue || 0;
      const newValue = performCalculation(currentVal, inputValue, operator);
      setPrevValue(newValue);
      setDisplayValue(String(newValue));
    }

    setWaitingForOperand(true);
    setOperator(nextOperator === '=' ? null : nextOperator);
    if (nextOperator === '=') {
      setPrevValue(null);
    }
  };

  return {
    displayValue,
    clearAll,
    toggleSign,
    inputPercent,
    inputDigit,
    inputDot,
    handleOperator,
  };
}

export default function App() {
  const {
    displayValue,
    clearAll,
    toggleSign,
    inputPercent,
    inputDigit,
    inputDot,
    handleOperator,
  } = useCalculator();

  const getFontSize = (value: string) => {
    if (value.length > 12) return '1.2rem';
    if (value.length > 9) return '1.8rem';
    if (value.length > 6) return '2.1rem';
    return '2.5rem';
  };

  return (
    <div className="calculator">
      <div className="display" style={{ fontSize: getFontSize(displayValue) }}>
        {displayValue}
      </div>
      <div className="keypad">
        <button className="btn btn-action" onClick={clearAll}>AC</button>
        <button className="btn btn-action" onClick={toggleSign}>+/-</button>
        <button className="btn btn-action" onClick={inputPercent}>%</button>
        <button className="btn btn-operator" onClick={() => handleOperator('÷')}>÷</button>

        <button className="btn btn-number" onClick={() => inputDigit('7')}>7</button>
        <button className="btn btn-number" onClick={() => inputDigit('8')}>8</button>
        <button className="btn btn-number" onClick={() => inputDigit('9')}>9</button>
        <button className="btn btn-operator" onClick={() => handleOperator('×')}>×</button>

        <button className="btn btn-number" onClick={() => inputDigit('4')}>4</button>
        <button className="btn btn-number" onClick={() => inputDigit('5')}>5</button>
        <button className="btn btn-number" onClick={() => inputDigit('6')}>6</button>
        <button className="btn btn-operator" onClick={() => handleOperator('-')}>-</button>

        <button className="btn btn-number" onClick={() => inputDigit('1')}>1</button>
        <button className="btn btn-number" onClick={() => inputDigit('2')}>2</button>
        <button className="btn btn-number" onClick={() => inputDigit('3')}>3</button>
        <button className="btn btn-operator" onClick={() => handleOperator('+')}>+</button>

        <button className="btn btn-number btn-zero" onClick={() => inputDigit('0')}>0</button>
        <button className="btn btn-number" onClick={inputDot}>.</button>
        <button className="btn btn-operator" onClick={() => handleOperator('=')}>=</button>
      </div>
    </div>
  );
}
